mapper.update:
UPDATE abstract_user u SET name = v.name, enabled = v.enabled, extra = COALESCE(v.extra, u.extra), owner_service_code = #{owner}, updated_at = #{updatedAt} FROM (VALUES
(CAST(#{u.id} AS BIGINT), CAST(#{u.name} AS VARCHAR), CAST(#{u.enabled} AS BOOLEAN), CAST(#{u.extra} AS JSONB))
) AS v(id, name, enabled, extra) WHERE u.id = v.id AND u.tenant_id = #{tenantId} AND u.delete_flag = 0
